sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers 
*/
function handler({api, event, helpers, imports}) {
    var value = event.payload.value;
    if(value == 'sentakusi'){
        api.setState('sentakusi',false);
        api.setState('jiyuu',true);
        api.setState('sakujo',true);
    }else if(value == 'jiyuu'){
        api.setState('sentakusi',true);
        api.setState('jiyuu',false);
        api.setState('sakujo',true);
    }else if(value == 'sakujo'){
        api.setState('sentakusi',true);
        api.setState('jiyuu',true);
        api.setState('sakujo',false);
        api.setState('shozoku','');
    }
}
